class Seat {
    lateinit var guest: String

    fun status() {
        if (this::guest.isInitialized) {
            println("taken by " + guest)
        } else {
            println("empty")
        }
    }
}

fun main() {
    val seat = Seat()
    seat.status()
    seat.guest = "Ana"
    seat.status()
}

